window.__BUNDLE__={"generatedAt":"2026-10-10T06:19:49.982476+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-03","archiveCutoff":"2021-10-11","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":354,"arxiv":1472,"total":1826},"freshness":{"latestPaperDate":"2026-10-09","latestPublishedDate":"2026-10-09","latestBatchCount":397,"newInLast24h":215,"newInLast48h":643},"historyTotal":22495,"topicCounts":{"Multi-Agent":2624,"Evaluation":12197,"Planning":1717,"Memory":454,"Code Agent":894,"Interpretability":805,"Agentic RAG":1356,"Agentic Search":1759,"RL for LLM":1265,"Reasoning":6206,"Hallucination":1077,"Post-Training":2563,"Alignment":2990,"World Model":403,"Tool Use":1300,"Agent Safety":2488,"Computer Use":312,"Reflection":807,"VLM Training":1689,"LLM Training":2791,"Fine-tuning":3456,"Multimodal Agent":128,"Agent Framework":852,"Error Attribution":140,"Data Engine":458},"count":36,"recentTotal":2371,"archiveCount":0,"archiveTotal":20124,"sources":{"hf":69,"arxiv":2302,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"pdf":"https://arxiv.org/pdf/2610.12126.pdf","id":"arxiv:2610.12126","date":"2026-10-09","source":"hf","upvotes":64,"arxiv":"https://arxiv.org/abs/2610.12126","hfUrl":"https://huggingface.co/papers/2610.12126","tags":["LLM Training","Fine-tuning"],"authors":["Jinkai Zhang","Jingyi Xu","Yuanhong Yu","Jiarui Guo","Ruizhen Hu","Hujun Bao","Xiaowei Zhou","Sida Peng"],"topics":["LLM Training","Fine-tuning"],"announceDate":"2026-10-09","title":"SuperNav: An Agentic Navigation System for Any Task in Any Scene","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12126","abstract":"General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical inter"},{"pdf":"https://arxiv.org/pdf/2610.11959.pdf","id":"arxiv:2610.11959","date":"2026-10-09","source":"hf","upvotes":58,"arxiv":"https://arxiv.org/abs/2610.11959","hfUrl":"https://huggingface.co/papers/2610.11959","tags":["Reflection"],"authors":["Xiaomi LLM-Core Team",":","Zongming Qiao","Ziyue Hua","Zirui Ou","Zihao Yue","Zihan Jiang","Zhuo Huang","Zhiyang Chen","Zhixian Zheng","Zhipeng Xu","Zhengrui Ma","Yuyang Hu","Yuhang Dong","Yuechen Zhang","Yudong Wang","Yuanxin Liu","Yixin Yang","Yishuo Cai","Yikai Zhao","Yihan Yan","Yifan Zhang","Yifan Song","Xiyu Wei","Xing Zhang","Xin Zhang","Xiaoqian Liu","Xiaodong Ji","Xiangwei Deng","Xueyu Guo","Wenhan Ma","Weimin Xiong","Weikun Wang","Weiji Zhuang","Shuo Liu","Shuhuai Ren","Shuhao Gu","Shimao Chen","Shijie Cao","Shihua Yu","Shicheng Li","Shengjie Zhou","Shaolei Zhang","Rang Li","Qiying Wang","Qingkai Fang","Qianli Chen","Minzheng Wang","Liwen Wang","Linli Yao","Linghao Zhang","Liangyu Cheng","Liang Zhao","Lei Li","Jinhao Dong","Jinyu Xiang","Jianyu Wei","Jiangshan Duo","Huaqiu Liu","Huanjie Fan","Hongyi Guan","Hongshen Xu","Hao Tian","Hanyu Li","Hailin Zhang","Gang Wang","Fuli Luo","Feng Wei","Dong Zhang","Dawei Zhu","Chiheng Lou","Chenhong He","Chenhao He","Chenghua Liu","Bowen Ye","Bowen Shen","Boshen Xu","Bo Yang","Bingquan Xia","Bangjun Xiao","Baixuan Xu","Zhouxiang Mao","Zhiyang Zhang","Zhixiang Xu","Zhenru Lin","Zhengju Tang","Zhaojun Huang","Yuzhe Weng","Yuxing Xiang","Yuxiao Li","Yuheng Yang","Yuhang Wang","Yuchen Liu","Yuanyuan Tian","Yuanliang Dong","Yu Cheng","Yongzhe He","Yongshun Liang","Yong Wang","Yiyan Wang","Yitian Gong","Yijie Zhang","Yanshu Xin","Xun Zhang","Xingjian Zhao","Wenyu Yang","Wenshan Huang","Wenhao Li","Tingwei Huang","Tianyu Yu","Tianyang Lu","Taoyu Yang","Sinan Du","Shutong Tian","Shulin Du","Shengfan Wang","Shanchuan Fang","Qihao Zhang","Qibin Yang","Qian Yu","Qian Tu","Pengrong Xie","Peipei Wang","Peidian Li","Minkun Guo","Mingchen Shao","Luohan Gao","Lijie Wang","Liang Shi","Kaiqi Chen","Kaiming Liu","Kaifei Wang","Kai Yang","Jinlong Xue","Jiechen Zhang","Jiaxuan Liu","Hongxu An","Hao Peng","Hanglong Lü","Guonan Wang","Feiyu Yang","Fanyu Cao","Fangyue Liu","Fan Cui","Cong Wang","Chun Chen","Chenxu Bai","Chengxuan Zhu","Chenghua Wang","Boyi Zeng"],"topics":["Reflection"],"announceDate":"2026-10-09","title":"MiMo-V2.6: Scaling Reinforcement Learning Towards Self-Improvement","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11959","abstract":"Reinforcement learning (RL) is the central training paradigm for advancing large foundation models towards self-improvement. This report introduces the MiMo-V2.6 series, an omni-modal family that pushes the frontier of model intelligence by scaling RL compute. Prior to RL, we conduct mid-training on a broad multimodal corpus to provide ample exploration space, and build a solid infrastructure on the pretrained hybrid-SWA architecture to support subsequent scale-up. We scale RL compute along three dimensions: (1) larger batches and higher throughput, with an asynchronous training that consumes 1,568 samples and 2.7-3.7B tokens per step at context lengths of up to 1M; (2) more diverse and complex environments, spanning code, general, visual, and cyber domains under a mixture of agent harnesses; and (3) more grader compute, via groupwise agentic grading that yields more accurate reward sign"},{"pdf":"https://arxiv.org/pdf/2610.12299.pdf","id":"arxiv:2610.12299","date":"2026-10-09","source":"hf","upvotes":44,"arxiv":"https://arxiv.org/abs/2610.12299","hfUrl":"https://huggingface.co/papers/2610.12299","tags":["Multi-Agent","World Model"],"authors":["Dahyun Chung","Siyoon Jin","Hyunwook Choi","Honggyu An","Junyoung Seo","Hyunsung Kim","Seung Wook Kim","Seungryong Kim"],"topics":["Multi-Agent","World Model"],"announceDate":"2026-10-09","title":"Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12299","abstract":"Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, a"},{"pdf":"https://arxiv.org/pdf/2610.12461.pdf","id":"arxiv:2610.12461","date":"2026-10-09","source":"hf","upvotes":31,"arxiv":"https://arxiv.org/abs/2610.12461","hfUrl":"https://huggingface.co/papers/2610.12461","tags":["VLM Training","World Model"],"authors":["You-Zhe Xie","Ting-Wei Chou","Yu-Hsuan Li","Kaipeng Zhang","Zhixiang Wang","Yu-Lun Liu"],"topics":["VLM Training","World Model"],"announceDate":"2026-10-09","title":"OuroWorld: Bringing Any 3D World Alive as Diverse, Endlessly Looping 3D Cinemagraphs","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12461","abstract":"Recent 3D world models generate photorealistic, explorable scenes that remain frozen in time. OuroWorld is a mask-free framework that turns any static 3D Gaussian Splatting scene into a 3D cinemagraph: a dynamic scene with vivid, diverse motion looping seamlessly from any viewpoint. A vision-language model infers plausible dynamics and guides a video model to synthesize a reference video, which we lift and complete into multi-view videos. To learn from this imperfect supervision, we propose Inconsistency-Robust Periodic 4DGS: a Fourier-series deformation field guarantees looping by construction, while a Grounded Drift Field anchored at the reference view absorbs cross-view inconsistency. Unlike prior Eulerian methods limited to fluid-like motion, we capture general deformation, object motion, and illumination change. We introduce a ground-truth-free evaluation covering vividness, natural"},{"pdf":"https://arxiv.org/pdf/2610.12289.pdf","id":"arxiv:2610.12289","date":"2026-10-09","source":"hf","upvotes":29,"arxiv":"https://arxiv.org/abs/2610.12289","hfUrl":"https://huggingface.co/papers/2610.12289","tags":["Code Agent","Evaluation","Reflection"],"authors":["Han Li","Lingxiang Hu","Jiacheng Huang","Ziqian Jiang","Jingkai Luo","Wei Gao","Yunfan Tan","Zun Wang","Jiaheng Liu"],"topics":["Code Agent","Evaluation","Reflection"],"announceDate":"2026-10-09","title":"TestPrism: Rethinking Test Evaluation Beyond a Single Reference","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12289","abstract":"Large language model (LLM) coding agents have advanced test generation across diverse programming tasks. However, the common practice of evaluating tests against a single reference solution overlooks alternative valid implementations and can overstate test quality. We introduce TestPrism, comprising 300 test tasks from 17 sources and 3000 candidate implementations, evenly split between valid and invalid solutions. Its primary metric, Joint Success Function, requires the generated tests to fail on the initial program state, accept every valid candidate, and reject every invalid candidate. Across fourteen baseline coding agent configurations, Joint Success Function reaches only 28.00%, whereas single reference success reaches 59.67%. Our analysis reveals missed behaviors, unsupported assertions, and faulty test construction. To address these weaknesses, we introduce TestHelix, which combin"},{"pdf":"https://arxiv.org/pdf/2610.11794.pdf","id":"arxiv:2610.11794","date":"2026-10-09","source":"hf","upvotes":27,"arxiv":"https://arxiv.org/abs/2610.11794","hfUrl":"https://huggingface.co/papers/2610.11794","tags":["Planning","Reflection","World Model"],"authors":["Haoyu Zhao","Zhengxu Yu","Zhiyuan He","Meng Fang","Rasul Tutunov","Haitham Bou-Ammar","Weilin Luo","Jun Wang"],"topics":["Planning","Reflection","World Model"],"announceDate":"2026-10-09","title":"Memento 3: Model-Based Recursive Self-Improvement through Reflective Rulebooks","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11794","abstract":"Learning to act in unfamiliar environments requires agents to infer how the world works and revise that understanding as new evidence arrives. Yet limited observations can support multiple world models that explain past interactions but predict different outcomes in unseen states. We introduce Memento 3, building on the Memento series to enable frozen LLM agents to continually learn explicit world models through external memory. The agent maintains a natural-language rulebook as persistent semantic memory, recording revisable hypotheses about environment dynamics while leaving unknown aspects underspecified. It compiles this rulebook into executable code for prediction and planning. Through a continual loop of observation, reflection, rule revision, compilation, and verification, the agent uses prediction errors to refine both the rulebook and its code. Updated code is accepted only when"},{"pdf":"https://arxiv.org/pdf/2610.12419.pdf","id":"arxiv:2610.12419","date":"2026-10-09","source":"hf","upvotes":19,"arxiv":"https://arxiv.org/abs/2610.12419","hfUrl":"https://huggingface.co/papers/2610.12419","tags":["Agentic Search","LLM Training","Evaluation","Data Engine"],"authors":["Hongyu Li","Manyuan Zhang","Kaituo Feng","Shu Chen","Dian Zheng","Hao Li","Hao Yu","Zhangquan Chen","Zoey Guo","Ray Zhang","Shaofei Huang","Tianrui Hui","Linjiang Huang","Si Liu"],"topics":["Agentic Search","LLM Training","Evaluation","Data Engine"],"announceDate":"2026-10-09","title":"OneSearch-VL: Unified Multimodal Deep Research Agent for Image and Video","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12419","abstract":"Single-image, multi-image, and video deep research require different visual operations but share a workflow of visual grounding, external retrieval, and fact composition. A key challenge is to preserve the dependencies linking localized visual anchors, entity relations, source-supported facts, and answer-producing operations. We introduce OneSearch-VL, a unified agent centered on the Visually Grounded Evidence Graph (VGEG), which encodes these dependencies as a shared task-level reference for data construction, process supervision, and operation-level evaluation. Our VGEG-based data engine constructs and verifies multi-image and video questions and filters expert trajectories. Using these data, we assemble OneSearch-VL-SFT-110K and OneSearch-VL-RL-10K for SFT and RL, respectively. We further derive the Evidence-aware Visual-Grounded Rubric reward (EVGR) from VGEG annotations to supervise"},{"pdf":"https://arxiv.org/pdf/2610.12442.pdf","id":"arxiv:2610.12442","date":"2026-10-09","source":"hf","upvotes":19,"arxiv":"https://arxiv.org/abs/2610.12442","hfUrl":"https://huggingface.co/papers/2610.12442","tags":["Alignment","Fine-tuning"],"authors":["Suhwan Cho","Yonwoo Choi","Soongjin Kim","Jicheol Park","Taegyu Lim"],"topics":["Alignment","Fine-tuning"],"announceDate":"2026-10-09","title":"LEGO: A Lifting-Free Approach for Exocentric-to-Egocentric Video Generation","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12442","abstract":"Generating an egocentric video from a single exocentric recording is a challenging case of novel view synthesis, as the two cameras share little overlap and much of the target view is unobserved. Current state-of-the-art methods reconstruct the scene explicitly by estimating depth, lifting the video into a point cloud, and re-rendering it from the egocentric camera to condition a video diffusion model. This deterministic mapping assigns each pixel to a single reprojected location, which preserves texture but translates depth errors into misplaced content. We ask what a video diffusion model should receive as its condition and propose a lifting-free answer: a learned view synthesizer, an LVSM-style transformer fine-tuned to render the egocentric view directly without depth, point clouds, or reprojection, resolving cross-view correspondence internally. In contrast, its probabilistic mappin"},{"pdf":"https://arxiv.org/pdf/2501.09223.pdf","id":"arxiv:2501.09223","date":"2026-10-09","source":"hf","upvotes":18,"arxiv":"https://arxiv.org/abs/2501.09223","hfUrl":"https://huggingface.co/papers/2501.09223","tags":["LLM Training","Reasoning","Alignment"],"authors":["Tong Xiao","Jingbo Zhu"],"topics":["LLM Training","Reasoning","Alignment"],"title":"Foundations of Large Language Models","url":"https://arxiv.org/abs/2501.09223","abstract":"This is a book about large language models. As indicated by the title, it primarily focuses on foundational concepts rather than comprehensive coverage of all cutting-edge technologies. The book is structured into six main chapters, each exploring a key area: pre-training, generative models, prompting, alignment, inference, and reasoning. It is intended for college students, professionals, and practitioners in natural language processing and related fields, and can serve as a reference for anyone interested in large language models."},{"pdf":"https://arxiv.org/pdf/2610.12343.pdf","id":"arxiv:2610.12343","date":"2026-10-09","source":"hf","upvotes":17,"arxiv":"https://arxiv.org/abs/2610.12343","hfUrl":"https://huggingface.co/papers/2610.12343","tags":["Reasoning","Planning","Evaluation"],"authors":["Xue Yang","Peiyuan Zhang","Yilun Zhu","Qihao Yang","Mingxin Liu","Xiangyu Zhao","Ziqian Fan","Zhaokai Wang","Yan Li","Yifan Yang","Xu Yang","Xiaosong Jia","Yue Zhou","Zhihang Zhong","Junchi Yan"],"topics":["Reasoning","Planning","Evaluation"],"announceDate":"2026-10-09","title":"Reasoning-Informed Visual Editing","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12343","abstract":"Large Multi-modality Models (LMMs) have made significant progress in visual understanding and generation, but still face challenges in visual editing, particularly in following complex instructions, preserving appearance consistency, and supporting flexible input formats. To study this gap, we introduce RISEBench, the first benchmark for evaluating Reasoning-Informed viSual Editing (RISE), and extend it to RISEBench++, a more comprehensive and fine-grained benchmark for this emerging task. RISEBench++ extends the taxonomy into a hierarchical scheme spanning six reasoning dimensions: Temporal, Causal, Spatial, Logical, and Counterfactual Reasoning, together with Hybrid Reasoning integrating multiple reasoning types across multi-turn edits. These dimensions are further decomposed into 12 subcategories and 65 fine-grained task types. We expand input formats to include multi-image conditioni"},{"pdf":"https://arxiv.org/pdf/2610.12229.pdf","id":"arxiv:2610.12229","date":"2026-10-09","source":"hf","upvotes":13,"arxiv":"https://arxiv.org/abs/2610.12229","hfUrl":"https://huggingface.co/papers/2610.12229","tags":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"authors":["Jinjing Zhao","Fangyun Wei","Yitong Wang","Xiuyu Wu","Yunuo Chen","Yang Yue","Sirui Zhang","Wenbo Wang","Hongyang Zhang","Dong Chen","Yan Lu","Chang Xu"],"topics":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-09","title":"VibeEdit: Image Editing with Canvas Instructions","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12229","abstract":"In text-guided image editing, describing the desired change is often straightforward, but identifying the intended object or region can be cumbersome, especially when several objects look alike. We introduce a new image editing interface that lets users place spatial marks and optional short notes directly on the image. Together, these annotations form a canvas instruction that specifies where to edit and what to change. Our editor, VibeEdit, follows these instructions to perform object addition, removal, replacement, attribute modification, and movement without a separate text prompt. We construct 1.55 million source-target edit pairs with object masks and structured edit descriptions, from which we render canvas instructions during training. We adapt Qwen-Image-Edit with layer-decoupled conditioning that separately encodes source images and canvas instructions for image editing. We tra"},{"pdf":"https://arxiv.org/pdf/2610.12423.pdf","id":"arxiv:2610.12423","date":"2026-10-09","source":"hf","upvotes":13,"arxiv":"https://arxiv.org/abs/2610.12423","hfUrl":"https://huggingface.co/papers/2610.12423","tags":["Evaluation"],"authors":["Siyu Chen","Zehan Wang","Jiayang Xu","Yihan Wu","Jialei Wang","Junming Chen","Ziang Zhang","Yutong Ying","Zhou Zhao"],"topics":["Evaluation"],"announceDate":"2026-10-09","title":"Pumpire: Unified Benchmark for Metric Distance Estimation","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12423","abstract":"We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and camera intrinsics separately or evaluate point-clouds with geometric similarity metrics, which cannot directly reflect models' point-to-point distance estimation capability, Pumpire directly assesses point-to-point distances from the reconstructed geometry. To this end, we collect a large-scale and diverse dataset (pumpire-6k) comprising 100 real-world scenes, each annotated with physically measured point-pair distances and containing 64 frames, for a total of 6,400 frames. Building on this dataset, we establish a holistic evaluation protocol that covers both image- and video-level 3D foundation models and enables direct assessment of po"},{"pdf":"https://arxiv.org/pdf/2610.12369.pdf","id":"arxiv:2610.12369","date":"2026-10-09","source":"hf","upvotes":12,"arxiv":"https://arxiv.org/abs/2610.12369","hfUrl":"https://huggingface.co/papers/2610.12369","tags":["VLM Training","Code Agent","Reflection","Data Engine"],"authors":["Kairui Hu","Siyuan Hu","Fangzhou Hong","Zhaoxi Chen","Ziwei Liu"],"topics":["VLM Training","Code Agent","Reflection","Data Engine"],"announceDate":"2026-10-09","title":"Embodied Turing Machines: Stateful Code for Robot Recursive Self-Improvement","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12369","abstract":"Most robot policies keep a model in the control loop: a VLA maps observations to actions, and an Agent Harness, such as Agent-as-Policy or Harness VLA queries a VLM for decision making at run time. We propose a different view: the embodied world is an Embodied Turing Machine, whose tape is the robot and environment state and rules are the policy. If this state can be represented accurately, the decision making can be written entirely in code. We therefore propose Code-Only-as-Policy (COAP): code measures and tracks the robot, environment, and task state from camera images and proprioception, and makes every decision from it. The same code applies across episodes, and different tasks share one library without a VLM or VLA in the loop. Compared with VLAs and Agent Harnesses, we analyze three advantages of COAP: (i) Explicit State: the state can be stored in code; (ii) Execution: code makes"},{"pdf":"https://arxiv.org/pdf/2610.12458.pdf","id":"arxiv:2610.12458","date":"2026-10-09","source":"hf","upvotes":11,"arxiv":"https://arxiv.org/abs/2610.12458","hfUrl":"https://huggingface.co/papers/2610.12458","tags":["Reasoning","Hallucination","Evaluation","Alignment"],"authors":["Zhongyu Yang","Jiale Tao","Ruitao Chen","Zuhao Yang","Yingfang Yuan","Xueliang Zhao","Auden","Kai Wang","Shuai Shao","Biao Wang","Steve Yves","Qinglin Lu"],"topics":["Reasoning","Hallucination","Evaluation","Alignment"],"announceDate":"2026-10-09","title":"OmniCapBench: A Deep-Structured Evaluation Framework for Fine-Grained Audio-Visual Captioning","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12458","abstract":"Multimodal large language models (MLLMs) are rapidly evolving toward continuous audio--visual reasoning, creating an urgent need for evaluations that expose their capability limits. Audio--visual captioning is an ideal diagnostic task, yet current benchmarks face a coupled trade-off: whole-caption scores provide coverage without localization, local probes provide localization without coverage, and unconstrained LLM judges introduce instability. We introduce OmniCapBench (Omni-Video Caption Benchmark), a benchmark that reframes audio--visual caption evaluation as a deep-structured diagnostic framework. OmniCapBench shifts the prediction target from free-form text to sets of atomic, verifiable evaluation units across three tracks: entity references, visual shots, and audio events, enabling reliable scoring with deterministic constraint checks and localized LLM-based semantic comparisons. W"},{"pdf":"https://arxiv.org/pdf/2610.12403.pdf","id":"arxiv:2610.12403","date":"2026-10-09","source":"hf","upvotes":10,"arxiv":"https://arxiv.org/abs/2610.12403","hfUrl":"https://huggingface.co/papers/2610.12403","tags":["VLM Training"],"authors":["Hongxing Li","Dingming Li","Yixin Li","Yong Du","Wenqi Zhang","Weiming Lu","Jun Xiao","Yueting Zhuang","Yongliang Shen"],"topics":["VLM Training"],"announceDate":"2026-10-09","title":"ViSkill: Reinforcing VLM Agents with Evolving Visual-Native Skills","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12403","abstract":"Skill-augmented agents improve sample efficiency by distilling successful trajectories into reusable strategies. Yet most existing approaches remain text-centric, linearizing spatial layouts and action-state correspondences into language that loses critical geometric structure. Recent efforts have begun incorporating visual evidence, but construct and update skills separately from policy optimization, leaving their mutual improvement underexplored. We propose ViSkill, a visual-native skill learning framework that encodes successful interactions as composite visual skill cards directly accessible to VLM agents. Retrieved skills guide both inference and reward shaping, while successful trajectories are distilled back into the library, forming a closed feedback loop in which skill accumulation and policy improvement reinforce each other. An optional cold-start mechanism further accelerates "},{"pdf":"https://arxiv.org/pdf/2610.12230.pdf","id":"arxiv:2610.12230","date":"2026-10-09","source":"hf","upvotes":8,"arxiv":"https://arxiv.org/abs/2610.12230","hfUrl":"https://huggingface.co/papers/2610.12230","tags":["Evaluation"],"authors":["Yitong Wang","Fangyun Wei","Jinjing Zhao","Sirui Zhang","Hongyang Zhang","Dong Chen","Bo Dai","Yan Lu"],"topics":["Evaluation"],"announceDate":"2026-10-09","title":"From Prompting to Composing: A Spatial Canvas Interface for Poster Generation","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12230","abstract":"Text prompting is an indirect interface for poster generation, requiring users to encode inherently two-dimensional composition intent into a one-dimensional sequence of words. We introduce a Spatial Canvas Interface that enables users to directly compose generation intent in space through four complementary binding types: semantic, identity, text, and pixel, together with Text Specifications for individual elements and global appearance. Based on this interface, we develop Compo, a poster generation model adapted from a pretrained image editing model to understand Spatial Canvas inputs and Text Specifications. Compo supports both direct inference, where users explicitly construct the canvas, and agentic mode, where a high-level request is automatically translated into a planned Spatial Canvas. To train Compo, we develop a scalable pipeline that automatically constructs supervision data "},{"pdf":"https://arxiv.org/pdf/2610.12402.pdf","id":"arxiv:2610.12402","date":"2026-10-09","source":"hf","upvotes":7,"arxiv":"https://arxiv.org/abs/2610.12402","hfUrl":"https://huggingface.co/papers/2610.12402","tags":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Hongxing Li","Jinyue Su","Dingming Li","Wenqi Zhang","Weiming Lu","Jun Xiao","Yueting Zhuang","Yongliang Shen"],"topics":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-10-09","title":"SpaceCast-Bench: Evaluating Predictive Spatial Reasoning in Vision-Language Models","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12402","abstract":"Existing spatial reasoning benchmarks mainly test spatial perception: reading off relations already visible in the input. Yet real-world spatial intelligence demands predictive spatial reasoning: constructing a scene from observations, anticipating how an intervention changes it, and reasoning about the unseen outcome. We introduce SpaceCast-Bench, the first benchmark to directly and diagnostically evaluate this capability. Built around an observe-transform-infer framework, its 3,862 questions from 182 real-world scenes span 16 task types at three levels: static perception, local prediction, and global prediction, progressively requiring scene understanding, spatial state updating, and relational inference over unobserved outcomes. Evaluating 21 models exposes a stark gap: the strongest model reaches only 58.0% against 87.2% human performance, while spatially specialized models remain ne"},{"pdf":"https://arxiv.org/pdf/2610.11816.pdf","id":"arxiv:2610.11816","date":"2026-10-09","source":"hf","upvotes":5,"arxiv":"https://arxiv.org/abs/2610.11816","hfUrl":"https://huggingface.co/papers/2610.11816","tags":["VLM Training","Evaluation"],"authors":["Yubo Sun","Chunyi Peng","Yukun Yan","Zhenghao Liu","Zhipeng Xu","Sen Mei","Linlin Xin","Zheni Zeng","Maosong Sun"],"topics":["VLM Training","Evaluation"],"announceDate":"2026-10-09","title":"Chaos in the Text: Revealing the Modality Preference in Mixed-Modality Retrievers","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11816","abstract":"Dense retrievers have made significant progress on text and image corpora, but whether these capabilities extend reliably to mixed corpora containing text, image, and fused text-image documents remains unclear. In this paper, we systematically examine retrievers across architectures and find that their performance is highly sensitive to modality composition. As image documents are progressively replaced with semantically corresponding text representations, retrieval performance follows a pronounced V-shaped curve, remaining strong on single-modality corpora but degrading substantially when modalities coexist. In particular, irrelevant text causes more severe degradation than an equal number of irrelevant images, a phenomenon we term Chaos in the Text. Further analysis reveals modality preference, whereby text representations receive systematically higher similarity scores, allowing irrel"},{"pdf":"https://arxiv.org/pdf/2610.12459.pdf","id":"arxiv:2610.12459","date":"2026-10-09","source":"hf","upvotes":4,"arxiv":"https://arxiv.org/abs/2610.12459","hfUrl":"https://huggingface.co/papers/2610.12459","tags":["Planning","World Model"],"authors":["Ankan Deria","Komal Kumar","Hisham Cholakkal","Fahad Shahbaz Khan","Salman Khan"],"topics":["Planning","World Model"],"announceDate":"2026-10-09","title":"WorldGuide: Goal-Directed Video World Model for Procedural Task Execution","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12459","abstract":"Video generators and video-based world models can synthesize plausible visual trajectories, but long-horizon procedural tasks require generation to adapt to what has actually been produced. A model must determine the next action from its generated state, execute that action, and recognize when the task is complete. Open-loop generation cannot adapt to execution outcomes, while existing closed-loop systems often rely on pretrained executors or indirect verification. This leaves a gap between deciding an action and successfully realizing it. We formulate procedural video generation as \\emph{closed-loop task execution in visual world space} and introduce \\textbf{WorldGuide}. Given only an initial image and a task goal, WorldGuide predicts an atomic action, generates its corresponding video clip, and uses the generated result to select the next action or terminate. The Planner and Executor a"},{"pdf":"https://arxiv.org/pdf/2610.12183.pdf","id":"arxiv:2610.12183","date":"2026-10-09","source":"hf","upvotes":4,"arxiv":"https://arxiv.org/abs/2610.12183","hfUrl":"https://huggingface.co/papers/2610.12183","tags":["Evaluation"],"authors":["Ming Chen","Rong-Xi Tan","Ke Xue","Yu-Jie Zhou","Taiye Lu","Zhi-Xuan Gao","Peng Xie","Zijun Shen","Chen Lu","Haopu Shang","Chao Qian"],"topics":["Evaluation"],"announceDate":"2026-10-09","title":"A Closer Look at Agentic BBO: Benchmarking LLM Agents for Black-Box Optimization","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12183","abstract":"Black-box optimization (BBO) arises in many scientific and engineering problems where objective evaluations are expensive and limited. Recent large language model (LLM) agents offer a new way to approach BBO by combining task semantics, computation, optimization tools, and feedback-driven decision making, showing great potential due to the integration with mathematically rigorous tools. However, existing agentic BBO studies use different task domains and system configurations, making their results difficult to compare and the effects of individual design choices hard to isolate. We therefore introduce AgenticBBO-Bench, a cross-domain benchmark for agentic BBO spanning synthetic functions, hyperparameter optimization, database tuning, chip design, and molecular design under a unified finite-budget evaluation protocol. In our experiments, agentic BBO achieves higher family-averaged scores "},{"pdf":"https://arxiv.org/pdf/2610.12452.pdf","id":"arxiv:2610.12452","date":"2026-10-09","source":"hf","upvotes":3,"arxiv":"https://arxiv.org/abs/2610.12452","hfUrl":"https://huggingface.co/papers/2610.12452","tags":["Code Agent","Evaluation","Alignment"],"authors":["Peter Kulits","Yiqing Xu","R. Kenny Jones","Cordelia Schmid","Jiajun Wu"],"topics":["Code Agent","Evaluation","Alignment"],"announceDate":"2026-10-09","title":"BrickBench: Evaluating Agentic Brick Design","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12452","abstract":"We propose BrickBench, a benchmark for agentic text-conditioned LEGO-set design. Given a prompt, an agent is tasked with producing an assembly that not only satisfies semantic and design criteria, but that can also be physically built. To do so, it must select parts from a discrete library and reason jointly about local and global constraints. We score validity, alignment, and design across three settings that vary in scale and part availability. We provide BrickAgent, an environment for coding agents to construct, inspect, and validate their designs. We find that leading agents largely satisfy verifiable physical and semantic requirements, but fall short of human designs. We release our benchmark and environment at http://www.brickben.ch"},{"pdf":"https://arxiv.org/pdf/2610.12360.pdf","id":"arxiv:2610.12360","date":"2026-10-09","source":"hf","upvotes":3,"arxiv":"https://arxiv.org/abs/2610.12360","hfUrl":"https://huggingface.co/papers/2610.12360","tags":["Evaluation"],"authors":["Kaiser Sun","Bernal Jimenez Gutierrez","Hongjun Liu","Jingyu Zhang","Jie Gao","Mark Dredze","Daniel Khashabi"],"topics":["Evaluation"],"announceDate":"2026-10-09","title":"Accurate but Not Humble: Evaluating Epistemic Humility in LLM Agents under Knowledge Conflict","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12360","abstract":"When retrieved evidence contradicts an agent's prior beliefs, does it revise its answer, acknowledge uncertainty, or persist with an incorrect conclusion? Existing evaluations of agentic systems focus primarily on task success, offering limited insight into how agents handle such conflicts. We propose to evaluate agents on epistemic humility (EH): the agent's willingness to recognize, act on, and communicate uncertainty during task execution. We operationalize EH through three trajectory-level behavioral dimensions: Identify, Solve, and Escalate (ISE). Through knowledge conflict, situations where the backbone language model's parametric knowledge contradicts the evidence it encounters, or where two contextual sources disagree, we evaluate two conflict settings: (1) controlled conflict and (2) naturally occurring conflict during multi-step agentic execution, each paired with matched no-co"},{"pdf":"https://arxiv.org/pdf/2610.10549.pdf","id":"arxiv:2610.10549","date":"2026-10-09","source":"hf","upvotes":3,"arxiv":"https://arxiv.org/abs/2610.10549","hfUrl":"https://huggingface.co/papers/2610.10549","tags":["Data Engine"],"authors":["Yipeng Li","Ashutosh Hathidara","Jane Lo","Harshavardhan Abichandani","Gunraj Singh","Atin Ghosh"],"topics":["Data Engine"],"announceDate":"2026-10-09","title":"Synthesis Through Simulation: Generating Coherent Enterprise Data via Scalable Agent-System Interaction","submittedDate":"2026-09-24","url":"https://arxiv.org/abs/2610.10549","abstract":"Tool-calling agents have become central to enterprise AI, yet training and evaluating them at scale remains severely constrained due to business and legal restrictions on enterprise systems, data, and database schemas. Tabular data synthesis offers a natural alternative, but its effectiveness is fundamentally limited by structural validity and schema availability, while procedure-based approaches yield the opposite weakness, typically lacking distributional fidelity without per-domain authoring. We introduce **Synthesis Through Simulation** (STS), a **schema--free** data synthesis paradigm in which an LLM agent generates data by executing operations against policy-enforcing APIs within simulated enterprise environments. Because data is generated through the same environment that defines what is valid, STS guarantees structural validity by construction while decoupling validity enforcemen"},{"pdf":"https://arxiv.org/pdf/2610.11366.pdf","id":"arxiv:2610.11366","date":"2026-10-09","source":"arxiv","upvotes":8,"arxiv":"https://arxiv.org/abs/2610.11366","hfUrl":"https://huggingface.co/papers/2610.11366","tags":["Post-Training","LLM Training","Reasoning","Code Agent","Evaluation"],"authors":["Rongxue Li","Meng Yang","Yiru Mao","Yongliang Tao","Lulu Hu","Bin Yang","Zhao Xu","Weihua Luo","Bowen Xu"],"topics":["Post-Training","LLM Training","Reasoning","Code Agent","Evaluation"],"announceDate":"2026-10-09","title":"SpatialOPSD: Self-Distilling Spatial Intelligence from Verified Coding Agent Traces","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11366","abstract":"Spatial coding agents significantly improve spatial reasoning in Multimodal Large Language Models (MLLMs) by using external tools to generate verified execution traces. However, this paradigm inherently suffers from prohibitive inference-time overhead and external dependencies. In this paper, we explore whether an MLLM can internalize this agentic capability to operate entirely tool-free. We begin with a simple observation: prompting an MLLM with summarized execution traces of a spatial coding agent naturally unlocks the model's internal spatial Chain-of-Thought (CoT). Motivated by this, we introduce SpatialOPSD, an on-policy self-distillation framework that internalizes spatial reasoning into a standalone MLLM by formulating verified agent traces as privileged information. To mitigate privileged-information leakage during distillation, we introduce Repetition-Aware Distillation, which c"},{"pdf":"https://arxiv.org/pdf/2610.10845.pdf","id":"arxiv:2610.10845","date":"2026-10-09","source":"arxiv","upvotes":7,"arxiv":"https://arxiv.org/abs/2610.10845","hfUrl":"https://huggingface.co/papers/2610.10845","tags":["Memory","Evaluation"],"authors":["Sietse Schelpe"],"topics":["Memory","Evaluation"],"announceDate":"2026-10-09","title":"Real Long-Term Memory for AI: A 50-Million-Token Window That Is Faster and Cheaper Than Recompute","submittedDate":"2026-10-07","url":"https://arxiv.org/abs/2610.10845","abstract":"A large language model can only use the text that fits in its context window, and it recomputes its internal key-value (KV) state for a prompt every time the prompt is sent. We test a memory layer, the public package galahad-kv, that saves the KV state of each block of about 16,000 tokens to encrypted local NVMe disk and loads it back later, byte-exact, without recomputing it. We ran it on 50,000,000 tokens of real public text, served through vLLM on one NVIDIA H100, with Gemma 4 12B and Gemma 4 31B. Every block we probed was loaded back from the encrypted store with no recompute (100 of 100, at depths from 0 to 50M tokens) on both models. Loading a block was 2.8x to 4.3x faster than recomputing it and used 8.8x to 12.3x less GPU energy, and GPU memory stayed flat over the whole 50M-token stream. Asked about facts planted millions of tokens earlier, the 12B model gave the right answer 82"},{"pdf":"https://arxiv.org/pdf/2610.11287.pdf","id":"arxiv:2610.11287","date":"2026-10-09","source":"arxiv","upvotes":5,"arxiv":"https://arxiv.org/abs/2610.11287","hfUrl":"https://huggingface.co/papers/2610.11287","tags":["Evaluation"],"authors":["Hanchen Xia","Baoyou Chen","Yutang Ge","Naihao Deng","Senqiao Yang","Zilong Dong","Weihao Yuan","Siyu Zhu"],"topics":["Evaluation"],"announceDate":"2026-10-09","title":"REMORY: Learning Residual Memory for Context Compaction","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11287","abstract":"Long-horizon agents compact their history to continue within a finite context window, but a textual summary alone may not support every subsequent decision. We introduce REMORY, a neural memory network that supplements the summary with a bounded sequence of soft memory tokens. Given the history and summary, the network learns to generate tokens that help a frozen LLM approximate the continuation it would produce with the full history. The tokens are conditioned on the summary and appended after it, forming an analogue of a residual connection along the sequence dimension. On SummHay, REMORY improves source attribution at nearly unchanged insight coverage and approaches the full-context joint score using only 5.2% of the input positions. Across long-horizon agent benchmarks, Qwen3.8-27B and GLM-5.3-Flash show consistent gains with residual memory. Both models also exhibit substantially fe"},{"pdf":"https://arxiv.org/pdf/2610.11570.pdf","id":"arxiv:2610.11570","date":"2026-10-09","source":"arxiv","upvotes":4,"arxiv":"https://arxiv.org/abs/2610.11570","hfUrl":"https://huggingface.co/papers/2610.11570","tags":["Reasoning"],"authors":["Pengxiang Li","Dilxat Muhtar","Di He","Guinan Su","Lu Yin","Shiwei Liu"],"topics":["Reasoning"],"announceDate":"2026-10-09","title":"Scaling to Tens of Thousands of Test-Time Iterations with Loop-Native Attention Residuals","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11570","abstract":"In this paper, we argue that looped Transformers need their own residual connections to prevent performance degradation as the number of iterations grows. We observe that increasing loop iterations can reduce reasoning accuracy: noisy state updates overwrite correct intermediate deductions and even undo completed solutions. This leaves subsequent iterations to recover lost information from an already degraded representation: once an error arises in an earlier loop, often as a result of long-range propagation through the recurrence, later loops find it difficult to correct. In this paper, we introduce InfiLoop, a loop-native residual connection that learns which past computations to retain and how much to accept from each new update. InfiLoop combines content-based weighting with learned temporal decay to maintain a running summary of recurrent states. An exact streaming recurrence keeps "},{"pdf":"https://arxiv.org/pdf/2610.12235.pdf","id":"arxiv:2610.12235","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.12235","tags":["Agentic Search","Post-Training","LLM Training","Reasoning","Evaluation"],"authors":["Zijun Wang","Zewen Liu","Minhua Lin","Zhaotian Weng","Zhan Shi","Bing He","Yisi Sang","Dakuo Wang","Benoit Dumoulin","Wei Jin","Yuyin Zhou","Cihang Xie","Hanqing Lu"],"topics":["Agentic Search","Post-Training","LLM Training","Reasoning","Evaluation","Reflection","World Model"],"announceDate":"2026-10-09","title":"Language Models as AI Research World Models","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12235","abstract":"AI research agents automate the cycle of proposing, implementing, and evaluating experiments, opening a path toward recursive self-improvement. Yet their ability to propose experiments outpaces their capacity to execute them in real environments, making outcome prediction a key capability for sustained self-improvement under limited experimental budgets. We investigate language models as Research World Models (RWMs), which predict the outcomes of candidate interventions across research environments. Our evaluation draws on over 2,600 experimental records from nine research environments spanning pretraining, post-training, and inference, representing more than 171,000 H100 GPU-hours of experimentation. Research knowledge acquired from real experimental experience improves RWM predictions of unseen interventions within the same environment (Spearman +0.27), and can be reused across environ"},{"pdf":"https://arxiv.org/pdf/2610.11345.pdf","id":"arxiv:2610.11345","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.11345","tags":["Multi-Agent","Reasoning","Evaluation","Reflection","RL for LLM"],"authors":["Wei Yang","Shawn Li","Yuehan Qin","Yawei Wang","Mingxi Wang","Shixuan Li","Tiankai Yang","Jiate Li","Jesse Thomason","Xuezhe Ma","Yue Zhao"],"topics":["Multi-Agent","Reasoning","Evaluation","Reflection","RL for LLM","Data Engine"],"announceDate":"2026-10-09","title":"SynCo: Data Synthesis Co-Training for Self-Evolving LLMs via Multi-Agent Reinforcement Learning","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11345","abstract":"Self-evolving LLM agents promise to improve autonomously through continual interaction and learning, reducing their dependence on manually curated supervision. Realizing this promise requires not only updating the agent, but also evolving its training experience as its capabilities change. However, most existing pipelines rely on static datasets or separately updated synthesis models, causing previously useful tasks to become trivial while overly difficult tasks remain uninformative. This growing mismatch between agent capability and training experience limits sustained self-improvement. To address this problem, we propose SynCo, an agentic data synthesis co-training framework for self-evolving LLMs based on multi-agent reinforcement learning. SynCo jointly optimizes two independently parameterized agents: a Synthesizer that constructs training tasks from the Reasoner's evolving capabili"},{"pdf":"https://arxiv.org/pdf/2610.11171.pdf","id":"arxiv:2610.11171","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.11171","tags":["LLM Training","Tool Use","Reasoning","Alignment","Fine-tuning"],"authors":["Runquan Gui","Hanzhu Chen","Zehao Wang","Hanxin Zhu","Xin Li","Zhibo Chen"],"topics":["LLM Training","Tool Use","Reasoning","Alignment","Fine-tuning","Multimodal Agent"],"announceDate":"2026-10-09","title":"VAMR: Multi-Question Agentic Reasoning for Efficient Long-Form Video Understanding","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11171","abstract":"Long-form video understanding often involves multiple questions about different aspects of the same recording. Yet existing video agents typically process each question through an isolated tool-use trajectory. This repeatedly restarts video exploration and memory construction, missing opportunities to acquire evidence jointly and progressively build a shared understanding that supports the complete question set. We introduce \\textbf{VAMR} (\\textbf{V}ideo \\textbf{A}gent for \\textbf{M}ulti-Question \\textbf{R}easoning), which coordinates all questions about a video through one shared tool-use trajectory. At each round, a persistent policy model can invoke tools for one or more unresolved questions and submit answers for questions with sufficient evidence. Question-conditioned visual perception retrieves fine-grained clues for several questions in one call, while layered multi-question memor"},{"pdf":"https://arxiv.org/pdf/2610.12176.pdf","id":"arxiv:2610.12176","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.12176","tags":["LLM Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"authors":["Hyunin Lee","Jinglue Xu","Jeffrey Seely","Donghyun Lee","Somayeh Sojoudi","Matei Zaharia","Yujin Tang"],"topics":["LLM Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning","Reflection"],"announceDate":"2026-10-09","title":"Recursive Self-Improvement through Multi-Agent Self-Supervision","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12176","abstract":"Recursive self-improvement (RSI) of a model on non-verifiable tasks, such as open-ended research, faces a supervision bottleneck when its outputs exceed what even human experts can reliably assess, leaving the model itself (optimizee) as the best available optimizer and evaluator. However, a single model instance struggles to critique and improve its own complex reasoning under this homogeneous loop. To address this, we propose Multi-Agent Self-Supervision (MASS), an RSI method that alternates between evolutionary workflow optimization and supervised fine-tuning on self-generated trajectories. Guided by early findings that multi-agent topologies excel at complex reasoning, MASS prompts a single base model to iteratively propose, execute, and self-evaluate multi-agent workflows. Through an evolutionary search constrained by structural guardrails, the model optimizes these computational-gr"},{"pdf":"https://arxiv.org/pdf/2610.12190.pdf","id":"arxiv:2610.12190","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.12190","tags":["Post-Training","LLM Training","Tool Use","Evaluation","Fine-tuning"],"authors":["Yudi Zhang","Mingyu Cao","Lu Yin","Mykola Pechenizkiy","Shiwei Liu"],"topics":["Post-Training","LLM Training","Tool Use","Evaluation","Fine-tuning","Reflection"],"announceDate":"2026-10-09","title":"DataSense-Bench: The First Step Toward an AI Scientist","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.12190","abstract":"As claims about recursive self-improvement (RSI) and artificial general intelligence (AGI) proliferate, we ask a simple question: do frontier AI models have a sense of data, i.e., can they reliably select the right data for training? We introduce DataSense-Bench to study this capability through the fundamental problem of data selection and performance forecasting in machine learning. We ask AI agents to select and rank candidate training subsets that can be used to fine-tune a small LLM model. Agents are allowed to inspect the data, write and execute analysis code, and run model forward passes, but can not train the model or access the actual evaluation tasks. We then fine-tune the base model on each selected subset and evaluate its post-training performance under a standardized protocol. We instantiate the benchmark in terminal problem solving and tool use, selecting trajectories from O"},{"pdf":"https://arxiv.org/pdf/2610.11810.pdf","id":"arxiv:2610.11810","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.11810","tags":["VLM Training","Reasoning","Planning","Evaluation","Alignment"],"authors":["Qixiang Chen","Cheng Zhang","Fucai Ke","Chi-Wing Fu","Jianfei Cai","Jingwen Ye"],"topics":["VLM Training","Reasoning","Planning","Evaluation","Alignment","Fine-tuning"],"announceDate":"2026-10-09","title":"Seek-and-View Reasoning for Multi-View Spatial Understanding","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11810","abstract":"Existing approaches to multi-view spatial reasoning operate largely on sparse input views. Vision-language models (VLMs) are thus restricted to understand a scene and infer spatial relations within these fixed views, leading to fragile cross-view alignment and geometry-to-language bottleneck. To address these issues, we formulate a novel Seek-and-View reasoning approach to find implicit cross-view spatial evidence by locating a question-relevant view to support the spatial reasoning. To realize this approach, we propose Vantage, a training-free model-agnostic reasoning framework that pairs a VLM with a 3D foundation model: a viewpoint-grounded reasoning stage for question analysis and view planning, followed by a geometry-grounded evidence augmentation stage to effectively synthesize and incorporate visual evidence into the final reasoning. Comprehensive experiments on six VLMs demonstra"},{"pdf":"https://arxiv.org/pdf/2610.11600.pdf","id":"arxiv:2610.11600","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.11600","tags":["Error Attribution","Multi-Agent","Tool Use","Reasoning","Evaluation"],"authors":["Jiaqi Liao","Yuanzhao Zhai","Huanxi Liu","Xu Zhang","Zheming Zhuang","Dawei Feng","Bo Ding","Huaimin Wang"],"topics":["Error Attribution","Multi-Agent","Tool Use","Reasoning","Evaluation"],"announceDate":"2026-10-09","title":"Error-Propagation Modeling for Failure Attribution in LLM-Based Multi-Agent Systems","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11600","abstract":"LLM-based multi-agent systems (MASs) are increasingly used to solve complex tasks through coordinated reasoning, tool use, and interaction with external resources. However, attributing failures in such systems remains challenging because the observed outcome often does not directly reveal the error responsible for the failed execution. In this work, the attribution target is the decisive error, defined as the agent--step pair whose correction would recover the failed execution. Existing approaches largely identify suspicious steps without explicitly modeling how errors propagate across interactions or persist in unresolved loops, making decisive errors difficult to distinguish from downstream failure symptoms. We propose \\textbf{E}rror-Propagation \\textbf{M}odeling for \\textbf{F}ailure \\textbf{A}ttribution (\\textbf{EMFA}). EMFA constructs a structured representation of the failed traject"},{"pdf":"https://arxiv.org/pdf/2610.11312.pdf","id":"arxiv:2610.11312","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.11312","tags":["VLM Training","Multi-Agent","Planning","Evaluation","Agent Framework"],"authors":["Yulin Fu","Junren Wang","Guangjing Yang","Zhangyuan Yu","Wanran Sun","Jiabao Zhou","Jin Yin","Qicheng Lao"],"topics":["VLM Training","Multi-Agent","Planning","Evaluation","Agent Framework"],"announceDate":"2026-10-09","title":"MedBenchAgent: Towards Systematic Automation of Medical VLM Benchmark Construction","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11312","abstract":"Large-scale construction of medical vision-language model (VLM) benchmarks is increasingly feasible with richly annotated imaging datasets and large language models (LLMs), yet existing automation largely focuses on generating evaluation items within predefined benchmark specifications. We study the broader problem of automatically deriving the specification itself: what to evaluate, which annotations support each task, and how to translate this evidence into reliable evaluation items. We formulate benchmark construction as constrained compilation, in which the benchmark specification is progressively derived from evaluation requirements, heterogeneous annotations, and medical knowledge. Based on this formulation, we introduce MedBenchAgent, a multi-agent framework with a Benchmark Intermediate Representation (BIR) that encodes task definitions, evidence mappings, evaluation protocols, a"},{"pdf":"https://arxiv.org/pdf/2610.11299.pdf","id":"arxiv:2610.11299","date":"2026-10-09","source":"arxiv","upvotes":0,"arxiv":"https://arxiv.org/abs/2610.11299","tags":["Multi-Agent","Tool Use","Reasoning","Code Agent","Evaluation"],"authors":["Yingda Shen","Yuxiang Wang","Kunyu Feng","Qinke Ni","Jiaqi Li","Minghao Hsu","Junan Zhang","Dekun Chen","Yutong Bian","Zhizheng Wu"],"topics":["Multi-Agent","Tool Use","Reasoning","Code Agent","Evaluation"],"announceDate":"2026-10-09","title":"DuplexAgent-RSI: Recursive Harness Improvement for Full-Duplex Voice Agent Collaboration","submittedDate":"2026-10-08","url":"https://arxiv.org/abs/2610.11299","abstract":"Voice agents are converging on a collaboration pattern: a full-duplex interaction model stays on the live channel as the entry to the conversation, while search, reasoning, and coding are handled through asynchronous delegation. A duplex model supports continuous listening and speaking, but complex reasoning and tool use may exceed its capabilities. A coding agent can plan and execute extended tasks, but its sequential interface is a poor fit for live conversation. Combining them requires a harness that coordinates task acceptance, progress, cancellation, replacement, and result delivery while keeping the conversation responsive. Existing harnesses often rely on coupled heuristics, making them difficult to improve systematically from evidence. We present DuplexAgent, a full-duplex collaboration system whose harness expresses this workflow as six editable modules, and Duplex-Harness-RSI, "}],"archive":[],"latestPath":"data/latest.json"};
